const raw = $input.first().json;

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const workflowName = raw.workflow?.name || 'unknown-workflow';
const nodeName = raw.execution?.lastNodeExecuted || raw.node?.name || 'unknown-node';
const errorMsg =
  raw.execution?.error?.message ||
  raw.error?.message ||
  (typeof raw.error === 'string' ? raw.error : JSON.stringify(raw.error || 'unknown error'));

const step = nodeName;
const incident_key = `${workflowName}:${nodeName}:${String(errorMsg).slice(0, 60).replace(/\s+/g, '-').toLowerCase()}`;

return [
  {
    json: {
      incident_id: uuidv4(),
      incident_key,
      severity: 'high',
      source: `n8n-error:${workflowName}`,
      step,
      timestamp: new Date().toISOString(),
      summary: `n8n workflow failed: ${workflowName} at node ${nodeName}`,
      error: errorMsg,
      context: {
        workflow_id: raw.workflow?.id,
        workflow_name: workflowName,
        execution_id: raw.execution?.id,
        execution_url: raw.execution?.url,
        node_name: nodeName,
        mode: raw.execution?.mode,
      },
    },
  },
];

